source2 = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    crosses = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 3 and grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 3:
                crosses.append((r, c, grid[r][c]))
    arm_owner = {}
    for i, (r, c, color) in enumerate(crosses):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            arm_owner[(r + dr, c + dc)] = i

    def paint_ray(r, c, color, dr, dc, owner):
        y, x = r, c
        while 0 <= y < h and 0 <= x < w:
            if grid[y][x] == 3:
                if arm_owner.get((y, x)) != owner:
                    break
            else:
                out[y][x] = color
            y += dr
            x += dc

    # Horizontal rays are drawn first; vertical rays take precedence at crossings.
    for i, (r, c, color) in enumerate(crosses):
        if color == 0:
            continue
        out[r][c] = color
        paint_ray(r, c - 1, color, 0, -1, i)
        paint_ray(r, c + 1, color, 0, 1, i)
    # A hollow cross projects a blank vertical stripe. Colored vertical rays
    # are drawn afterward and take precedence where they intersect it.
    for r, c, color in crosses:
        if color == 0:
            for y in range(h):
                out[y][c] = 0
    for i, (r, c, color) in enumerate(crosses):
        if color == 0:
            continue
        out[r][c] = color
        paint_ray(r - 1, c, color, -1, 0, i)
        paint_ray(r + 1, c, color, 1, 0, i)
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 3
    return out
'''
